# Pure Year 1, Chapter 13: integration.
from sympy import symbols, Rational as Q, sqrt, integrate, diff, simplify, solve, Abs
x, k, p, a, t, c = symbols('x k p a t c', real=True)
def ind(qid, f, want): exact(qid, simplify(diff(want, x) - f), 0)          # want is an antiderivative of f
def de(qid, f, lo, hi, want): exact(qid, integrate(f, (x, lo, hi)) - want, 0)
def area(qid, f, lo, hi, want):
    """Total area between y = f and the axis, splitting at roots."""
    rs = sorted(set([lo, hi] + [r for r in solve(f, x) if r.is_real and lo < r < hi]))
    exact(qid, sum(Abs(integrate(f, (x, rs[i], rs[i + 1]))) for i in range(len(rs) - 1)) - want, 0)
def setq(qid, got, want):
    global count
    count += 1
    if got != want: fails.append(f'{qid}: worked out {got}, answer says {want}')

# 13.1, 13.2
for qid, f, F in (('1', x**3, x**4/4), ('2', 5, 5*x), ('3', x**-2, -1/x), ('4', sqrt(x), Q(2, 3)*x**Q(3, 2)), ('5', 6*x**2, 2*x**3), ('6', 1/sqrt(x), 2*sqrt(x)),
                  ('7', 4*x**3 - 2*x, x**4 - x**2), ('8', 3/x**2, -3/x), ('9', x**Q(2, 3), Q(3, 5)*x**Q(5, 3)), ('10', 4*x**-3, -2*x**-2), ('11', 6*sqrt(x), 4*x**Q(3, 2)),
                  ('12', 5*x**Q(3, 2), 2*x**Q(5, 2)), ('14', x**Q(-5, 4), -4*x**Q(-1, 4)), ('15', 3*x**2 - 4/x**2, x**3 + 4/x + 2)):
    ind('P13.1-' + qid, f, F)
check('P13.1-15b', (x**3 + 4/x + 2).subs(x, 1), 7, 0); check('P13.1-15c', (x**3 + 4/x + 2).subs(x, 2), 12, 0)
for qid, f, F in (('1', 2*x + 3, x**2 + 3*x), ('2', 3*x**2 - 4*x + 5, x**3 - 2*x**2 + 5*x), ('3', x**3 + x, x**4/4 + x**2/2), ('4', (x + 2)**2, x**3/3 + 2*x**2 + 4*x),
                  ('5', 4*sqrt(x) - 1/x**2, Q(8, 3)*x**Q(3, 2) + 1/x), ('6', x*(x - 3), x**3/3 - Q(3, 2)*x**2), ('7', (x**2 + 1)/x**2, x - 1/x),
                  ('8', (2*x + 1)*(x - 4), Q(2, 3)*x**3 - Q(7, 2)*x**2 - 4*x), ('9', (x + 3)/sqrt(x), Q(2, 3)*x**Q(3, 2) + 6*sqrt(x)), ('10', 3 - 2/x**3, 3*x + x**-2),
                  ('11', (sqrt(x) + 1)**2, x**2/2 + Q(4, 3)*x**Q(3, 2) + x), ('12', (x**2 - 4)/(x + 2), x**2/2 - 2*x), ('13', (2*x**3 + 5*x)/x, Q(2, 3)*x**3 + 5*x),
                  ('14', (1 + x)**3, x + Q(3, 2)*x**2 + x**3 + x**4/4), ('15', (x**2 - 3)**2/x**2, x**3/3 - 6*x - 9/x + 12)):
    ind('P13.2-' + qid, f, F)
check('P13.2-15c', (x**3/3 - 6*x - 9/x + 12).subs(x, 3), 0, 0)

# 13.3: (antiderivative with the constant found, point it must pass through)
for qid, f, F, P in (('1', 2*x, x**2 + 3, (0, 3)), ('2', 4, 4*x + 3, (1, 7)), ('3', 3*x**2, x**3 + 2, (2, 10)), ('4', 6*x**2 - 2, 2*x**3 - 2*x + 5, (1, 5)),
                     ('5', 2*x - 5, (x - 2)*(x - 3), (2, 0)), ('6', 1/x**2, 5 - 1/x, (1, 4)), ('7', 3*sqrt(x), 2*x**Q(3, 2) + 4, (4, 20)), ('8', 4*x - 3, 2*x**2 - 3*x - 1, (2, 1)),
                     ('9', (x + 1)*(x - 3), x**3/3 - x**2 - 3*x + 2, (0, 2)), ('10', x - 4/x**2, x**2/2 + 4/x + 1, (2, 5)), ('11', 2*x**2, Q(2, 3)*x**3 + 1, (3, 19)),
                     ('12', 3*x**2 - 6*x, x**3 - 3*x**2 + 4, (2, 0)), ('15', 2*x - 16/x**2, x**2 + 16/x - 7, (1, 10))):
    ind('P13.3-' + qid, f, F); check('P13.3-' + qid + 'p', F.subs(x, P[0]), P[1], 0)
f13 = x**3 + 2*x - 1; exact('P13.3-13', (diff(f13, x, 2) - 6*x)**2 + (diff(f13, x).subs(x, 1) - 5)**2 + (f13.subs(x, 1) - 2)**2, 0)
check('P13.3-14', (t**3 - 2*t**2 + 2).subs(t, 3), 11, 0); check('P13.3-15', (x**2 + 16/x - 7).subs(x, 2), 5, 0)

# 13.4
for qid, f, lo, hi, w in (('1', x**2, 0, 2, Q(8, 3)), ('2', 2*x + 1, 1, 3, 10), ('3', 3*x**2 + 1, 0, 1, 2), ('4', sqrt(x), 1, 4, Q(14, 3)), ('5', 1/x**2, 1, 2, Q(1, 2)),
                          ('6', x**3 - x, -1, 2, Q(9, 4)), ('7', (x - 1)*(x - 3), 0, 3, 0), ('8', sqrt(x) - 1/sqrt(x), 1, 9, Q(40, 3)), ('10', (x**2 + 1)/x**2, 1, 2, Q(3, 2)),
                          ('11', 4 - x**2, -2, 2, Q(32, 3)), ('14', (x - 2)/sqrt(x), 4, 9, Q(26, 3))):
    de('P13.4-' + qid, f, lo, hi, w)
setq('P13.4-9', [s for s in solve(integrate(2*x, (x, 0, k)) - 9, k) if s > 0], [3]); setq('P13.4-12', [s for s in solve(integrate(2*x - 3, (x, 1, a)) - 6, a) if s > 1], [4])
setq('P13.4-13', [s for s in solve(integrate(k - x, (x, 0, k)) - 8, k) if s > 0], [4]); setq('P13.4-15', solve(integrate(3*x**2 + p*x, (x, 1, 3)) - 30, p), [1])
de('P13.4-15b', 3*x**2 + x, 0, 2, 10); de('P13.4-15c', 3*x**2 + x, -1, 1, 2)

# 13.5 - 13.6
for qid, f, lo, hi, w in (('P13.5-1', 3*x**2, 0, 2, 8), ('P13.5-2', x + 1, 1, 3, 6), ('P13.5-3', x**3, 0, 2, 4), ('P13.5-4', x**2 + 1, 0, 2, Q(14, 3)), ('P13.5-5', 4*x - x**2, 0, 4, Q(32, 3)),
                          ('P13.5-6', sqrt(x), 0, 9, 18), ('P13.5-7', 1/x**2, 1, 4, Q(3, 4)), ('P13.5-8', (x - 1)*(3 - x), 1, 3, Q(4, 3)), ('P13.5-9', x*(x - 2)**2, 0, 2, Q(4, 3)),
                          ('P13.5-10', 6*x**2 - x**3, 0, 6, 108), ('P13.5-12', x + 4/x**2, 1, 4, Q(21, 2)), ('P13.5-13', 9 - x**2, 0, 3, 18), ('P13.5-14', sqrt(x)*(4 - x), 0, 4, Q(128, 15)),
                          ('P13.5-15', x**3 - 6*x**2 + 9*x, 0, 3, Q(27, 4)), ('P13.6-1', x**2 - 2*x, 0, 2, Q(4, 3)), ('P13.6-2', x**2 - 4, -2, 2, Q(32, 3)), ('P13.6-4', x**3, -2, 0, 4),
                          ('P13.6-5', x**3 - x, -1, 1, Q(1, 2)), ('P13.6-6', x*(x - 3), 0, 3, Q(9, 2)), ('P13.6-8', x**2 - 4*x + 3, 0, 3, Q(8, 3)), ('P13.6-9', x*(x - 1)*(x - 2), 0, 2, Q(1, 2)),
                          ('P13.6-10', x**2 - 6*x + 5, 1, 5, Q(32, 3)), ('P13.6-11', 1 - x**2, 0, 2, 2), ('P13.6-12', x**3 - 4*x, -2, 2, 8), ('P13.6-14', x**3 - 3*x**2 + 2*x, 0, 3, Q(11, 4)),
                          ('P13.6-15', x**2*(x - 2), 0, 3, Q(59, 12))):
    area(qid, f, lo, hi, w)
setq('P13.5-11', solve(integrate(k*x**2, (x, 0, 3)) - 18, k), [2]); de('P13.6-1b', x**2 - 2*x, 0, 2, -Q(4, 3)); de('P13.6-7', x**2 - 4*x + 3, 0, 3, 0); de('P13.6-15b', x**2*(x - 2), 0, 3, Q(9, 4))
de('P13.6-13', x**2 - 6*x, 0, 6, -36)

# 13.7 (top - bottom over the stated limits)
for qid, f, lo, hi, w in (('1', 2*x - x**2, 0, 2, Q(4, 3)), ('2', x - x**2, 0, 1, Q(1, 6)), ('3', 1 - x**2, -1, 1, Q(4, 3)), ('4', 4 - x**2, -2, 2, Q(32, 3)), ('5', 3*x - x**2, 0, 3, Q(9, 2)),
                          ('6', 4*x - x**2, 0, 4, Q(32, 3)), ('7', 4 - x**2 - 3*x, 0, 1, Q(13, 6)), ('8', 2*x + 3 - x**2, -1, 3, Q(32, 3)), ('9', sqrt(x) - x/2, 0, 4, Q(4, 3)),
                          ('10', x - x**3, 0, 1, Q(1, 4)), ('11', 8 - 2*x**2, -2, 2, Q(64, 3)), ('13', 3*x - x**2, 0, 3, Q(9, 2)), ('14', -x**2 + 4*x - 3, 1, 3, Q(4, 3)), ('15', -x**2 + 5*x - 4, 1, 4, Q(9, 2))):
    de('P13.7-' + qid, f, lo, hi, w)
setq('P13.7-limits', [sorted(solve(x**2 - 2*x, x)), sorted(solve(x**2 - 2*x - 3)), sorted(solve(sqrt(x) - x/2, x)), sorted(solve(x**2 - 4*x + 3)), sorted(solve(x**2 - 5*x + 4))],
     [[0, 2], [-1, 3], [0, 4], [1, 3], [1, 4]])
de('P13.7-12', x**2, 0, 1, Q(1, 3)); check('P13.7-12b', Q(1, 3) - Q(1, 2)*Q(1, 2)*1, Q(1, 12), 0); de('P13.7-15c', x**2 - 4*x + 5, 1, 4, 6)
